{
  "findings": [
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that even with chat set to \"no one\" Roblox still allows in‑game chat if the game itself includes chat.",
      "stance": "risk",
      "quote": "even when chat is set to \"no one,\" if a mini-game has chat built into the game itself, it can't be disabled."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that experience chat controls who your child can communicate with inside supported experiences.",
      "stance": "mitigation",
      "quote": "Experience chat controls who your child can communicate with inside supported experiences."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that experience direct chat refers to private or one‑to‑one direct message features within some games.",
      "stance": "risk",
      "quote": "Experience direct chat refers to private or one-to-one direct message features within some games."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that party chat allows a child to group up with people on their friends list and chat within a shared experience.",
      "stance": "risk",
      "quote": "Party chat is the option that allows your kid to group up with the people in their friends list and chat within a shared experience."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that users can write text on signs to communicate with everyone playing the same game, bypassing chat controls.",
      "stance": "risk",
      "quote": "Chatting on \"signs\" is another way that kids can get around parental controls that disable chats."
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "A parent reports that Roblox offers in‑app purchases and a virtual currency (Robux) that can be spent on items.",
      "stance": "neutral",
      "quote": "Spending/Robux: You can set a monthly spending limit on how much money your child can spend on Roblox."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "A parent reports that Roblox collects visibility data and may share it with third parties for ad personalization.",
      "stance": "risk",
      "quote": "Visibility refers to who can see your kid's current experience and join them."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "A parent reports that Roblox uses automated moderation to limit sharing of personal information.",
      "stance": "mitigation",
      "quote": "Roblox uses automated moderation systems to limit the sharing of personal information and inappropriate content."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox requires an age check before allowing chat, and users under 16 cannot access experiences labeled with sensitive issues unless changed.",
      "stance": "mitigation",
      "quote": "The sensitive issues content label is applied to experiences that are primarily themed on current social, political, or religious issues. By default, users under 16 cannot access experiences that are labeled as including sensitive issues."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ contain violent or intense content such as punching, stomping, shooting, or fiery car accidents.",
      "stance": "risk",
      "quote": "This \"Baddies\" game is labeled for age 5+ and encourages punching, stomping, shooting, and other violence as part of the opening tutorial."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ can show intense scenes like fiery car accidents within seconds.",
      "stance": "risk",
      "quote": "Within seconds, this \"Street Code\" game showed an intense, fiery car accident and prompted the player to decide whether to shoot or save an officer."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory fines or lawsuits related to child privacy or data collection.",
      "stance": "risk",
      "quote": "Roblox has been fined by the FTC for collecting children's data without parental consent and for failing to obtain verifiable parental consent before allowing under‑13 users to chat."
    }
  ]
}
